	@Test
	void genericProfileRejectsUnpinnedDatasetAndForgedMetadata() throws Exception {
		Path bundle = temporaryDirectory.resolve("generic-identities");
		ThemeOracleBundleTool.generate(bundle, Theme.ADAPTIVE_FILTER_PLACEMENT);
		Path manifestPath = bundle.resolve(ThemeOracleBundleTool.MANIFEST_FILE);
		ObjectNode original = (ObjectNode) JSON.readTree(Files.readAllBytes(manifestPath));
		List<ManifestMutation> mutations = List.of(
				new ManifestMutation("theme", root -> root.put("theme", "DATA_TRANSFORMATION")),
				new ManifestMutation("profile", root -> object(root, "fixture").put("profile", "other")),
				new ManifestMutation("fractional statement count", root -> object(root, "fixture")
						.put("statementCount", 29.5)),
				new ManifestMutation("query hash", root -> query(root, 0).put("querySha256", "wrong")),
				new ManifestMutation("unproved numeric slot", root -> query(root, 0)
						.putArray("computedNumericVariables")
						.add("selectedProbe")),
				new ManifestMutation("unregistered ordering", root -> query(root, 0).put("orderFile", "other.json")));
		for (ManifestMutation mutation : mutations) {
			ObjectNode changed = original.deepCopy();
			mutation.edit().accept(changed);
			writeManifest(manifestPath, changed);
			assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle), mutation.name());
		}

		Path dataset = bundle.resolve(ThemeOracleBundleTool.DATASET_FILE);
		Files.writeString(dataset, Files.readString(dataset) + "# changed bytes\n", StandardCharsets.UTF_8);
		ObjectNode forged = original.deepCopy();
		object(forged, "dataset").put("bytes", Files.size(dataset));
		object(forged, "dataset").put("sha256", sha256(dataset));
		writeManifest(manifestPath, forged);
		assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle),
				"manifest cannot self-authorize different dataset bytes");
	}

