	@Test
	void socialVerifierPinsProfileCatalogAndNumericProvenance() throws Exception {
		Path bundle = temporaryDirectory.resolve("social-identities");
		ThemeOracleBundleTool.generate(bundle, Theme.SOCIAL_MEDIA);
		Path manifestPath = bundle.resolve(ThemeOracleBundleTool.MANIFEST_FILE);
		ObjectNode original = (ObjectNode) JSON.readTree(Files.readAllBytes(manifestPath));
		List<ManifestMutation> mutations = List.of(
				new ManifestMutation("theme", root -> root.put("theme", "REAL_ESTATE")),
				new ManifestMutation("profile", root -> object(root, "fixture").put("profile", "other")),
				new ManifestMutation("fractional user count", root -> object(object(root, "fixture"),
						"fixtureActualCounts").put("user", 18.5)),
				new ManifestMutation("query hash", root -> query(root, 0).put("querySha256", "wrong")),
				new ManifestMutation("numeric proof", root -> query(root, 2).putArray("computedNumericVariables")
						.add("unproven")));
		for (ManifestMutation mutation : mutations) {
			ObjectNode changed = original.deepCopy();
			mutation.edit().accept(changed);
			writeManifest(manifestPath, changed);
			assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle), mutation.name());
		}
		writeManifest(manifestPath, original);
		ThemeOracleBundleTool.verify(bundle);
		Path unsupported = temporaryDirectory.resolve("unsupported");
		assertThrows(IllegalArgumentException.class,
				() -> ThemeOracleBundleTool.generate(unsupported, Theme.MEDICAL_RECORDS));
		assertFalse(Files.exists(unsupported), "unsupported themes must be rejected before writing files");
	}

