	@Test
	void verifierRequiresPolicyIdentityAndIndependentlyProvenVariables() throws Exception {
		Path bundle = temporaryDirectory.resolve("comparison-policy-bundle");
		ThemeOracleBundleTool.generate(bundle);
		Path manifestPath = bundle.resolve(ThemeOracleBundleTool.MANIFEST_FILE);
		ObjectNode manifest = (ObjectNode) JSON.readTree(Files.readAllBytes(manifestPath));
		ObjectNode comparison = (ObjectNode) manifest.path("comparisonPolicy");
		ObjectNode q0 = (ObjectNode) manifest.path("queries").get(0);
		assertEquals(ComputedNumericBagPolicy.POLICY_ID, comparison.path("id").textValue());
		assertEquals("avgPrice", q0.path("computedNumericVariables").get(0).textValue());

		comparison.put("id", "unknown-policy");
		writeManifest(manifestPath, manifest);
		assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle));
		comparison.put("id", ComputedNumericBagPolicy.POLICY_ID);
		comparison.put("version", ComputedNumericBagPolicy.POLICY_VERSION + 1);
		writeManifest(manifestPath, manifest);
		assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle));
		comparison.put("version", ComputedNumericBagPolicy.POLICY_VERSION);
		q0.putArray("computedNumericVariables").add("district");
		writeManifest(manifestPath, manifest);
		assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle));
		q0.remove("computedNumericVariables");
		writeManifest(manifestPath, manifest);
		assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle));
	}

