	@Test
	void fixtureConversionRejectsDirectionalLiteralsTripleTermsAndNamedGraphs() {
		var vf = SimpleValueFactory.getInstance();
		var subject = vf.createIRI("urn:subject");
		var predicate = vf.createIRI("urn:predicate");
		Model directional = new LinkedHashModel();
		directional.add(subject, predicate, vf.createLiteral("value", "en", Literal.BaseDirection.LTR));
		Model triple = new LinkedHashModel();
		triple.add(subject, predicate, vf.createTripleTerm(subject, predicate, vf.createLiteral("value")));
		Model named = new LinkedHashModel();
		named.add(subject, predicate, vf.createLiteral("value"), vf.createIRI("urn:graph"));
		assertAll(
				() -> assertFixtureRejected(directional),
				() -> assertFixtureRejected(triple),
				() -> assertFixtureRejected(named));
	}

	@Test
	void fixtureConversionPreservesValidLanguageAndNumericLiterals() {
		var vf = SimpleValueFactory.getInstance();
		var subject = vf.createIRI("urn:subject");
		var values = List.of(vf.createLiteral("Bonjour", "FR-ca"), vf.createLiteral("001.00", XSD.DECIMAL),
				vf.createLiteral("plain"));
		Model fixture = new LinkedHashModel();
		for (int i = 0; i < values.size(); i++) {
			fixture.add(subject, vf.createIRI("urn:predicate:" + i), values.get(i));
		}
		var dataset = ThemeOracleBundleTool.jenaDataset(fixture);
		dataset.begin(org.apache.jena.query.ReadWrite.READ);
		try {
			var model = dataset.getDefaultModel();
			for (int i = 0; i < values.size(); i++) {
				var statement = model.getProperty(model.createResource(subject.stringValue()),
						model.createProperty("urn:predicate:" + i));
				assertEquals(values.get(i), ThemeOracleBundleTool.toRdf4j(statement.getObject()));
			}
		} finally {
			dataset.end();
			dataset.close();
		}
	}

