	@Test
	void verifierRejectsFractionalOrderFileQueryIdentities() throws Exception {
		Path bundle = temporaryDirectory.resolve("fractional-order-identities");
		ThemeOracleBundleTool.generate(bundle);
		Path manifestPath = bundle.resolve(ThemeOracleBundleTool.MANIFEST_FILE);
		ObjectNode manifest = (ObjectNode) JSON.readTree(Files.readAllBytes(manifestPath));
		for (int index : List.of(2, 11)) {
			ObjectNode record = query(manifest, index);
			Path orderPath = bundle.resolve(ThemeOracleBundleTool.QUERY_DIRECTORY)
					.resolve(record.path("orderFile").textValue());
			byte[] original = Files.readAllBytes(orderPath);
			ObjectNode order = (ObjectNode) JSON.readTree(original);
			order.put("queryIndex", index + 0.5);
			Files.writeString(orderPath, JSON.writerWithDefaultPrettyPrinter().writeValueAsString(order) + "\n",
					StandardCharsets.UTF_8);
			record.put("orderSha256", sha256(orderPath));
			writeManifest(manifestPath, manifest);
			assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle), "query " + index);
			Files.write(orderPath, original);
			record.put("orderSha256", sha256(orderPath));
		}
	}

	@Test
	void generatedFixtureHasAndPinsTheSupportedTermAndGraphScope() throws Exception {
		Model fixture = new LinkedHashModel(RealEstateOracleFixtureProfile.generateBase());
		RealEstateOracleFixtureProfile.addWitnessOverlay(fixture);
		assertFalse(fixture.isEmpty());
		fixture.forEach(statement -> {
			assertNull(statement.getContext());
			Value value = statement.getObject();
			assertFalse(value instanceof TripleTerm);
			if (value instanceof Literal literal) {
				assertEquals(Literal.BaseDirection.NONE, literal.getBaseDirection());
			}
		});
		Path bundle = temporaryDirectory.resolve("scope-bundle");
		ThemeOracleBundleTool.generate(bundle);
		JsonNode manifest = JSON.readTree(Files.readAllBytes(bundle.resolve(ThemeOracleBundleTool.MANIFEST_FILE)));
		JsonNode scope = manifest.path("fixture").path("scope");
		assertEquals("default-graph-only", scope.path("graphs").textValue());
		assertTrue(scope.path("directionalLiterals").isBoolean());
		assertFalse(scope.path("directionalLiterals").booleanValue());
		assertTrue(scope.path("tripleTerms").isBoolean());
		assertFalse(scope.path("tripleTerms").booleanValue());
		ObjectNode changed = ((ObjectNode) manifest).deepCopy();
		object(object(changed, "fixture"), "scope").put("directionalLiterals", true);
		writeManifest(bundle.resolve(ThemeOracleBundleTool.MANIFEST_FILE), changed);
		assertThrows(IllegalStateException.class, () -> ThemeOracleBundleTool.verify(bundle));
	}

	private static void assertFixtureRejected(Model fixture) {
		assertThrows(IllegalArgumentException.class, () -> {
			var dataset = ThemeOracleBundleTool.jenaDataset(fixture);
			dataset.close();
		});
	}

	private record ManifestMutation(String name, Consumer<ObjectNode> edit) {
	}

	private static ObjectNode object(ObjectNode parent, String field) {
		return (ObjectNode) parent.path(field);
	}

	private static ObjectNode query(ObjectNode root, int index) {
		return (ObjectNode) root.path("queries").get(index);
	}

	private static void writeManifest(Path manifestPath, ObjectNode manifest) throws Exception {
		Files.writeString(manifestPath, JSON.writerWithDefaultPrettyPrinter().writeValueAsString(manifest) + "\n",
				StandardCharsets.UTF_8);
	}

	private static String sha256(Path path) throws Exception {
		return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path)));
	}
